import sys


def next_version(current, messages):
    """current: 'MAJOR.MINOR.PATCH'. messages: commit messages since that release. A message containing 'BREAKING CHANGE', or whose type ends in '!' before the ':' (like 'feat!:'), is a major bump; else any message starting 'feat' is minor; else any starting 'fix' is patch. Return the new version, or 'no release'."""
    major, minor, patch = (int(x) for x in current.split("."))
    bump = 0                                       # 0 none, 1 patch, 2 minor, 3 major
    for message in messages:
        kind = message.split(":", 1)[0] if ":" in message else ""
        if "BREAKING CHANGE" in message or kind.endswith("!"):
            bump = 3
        elif message.startswith("feat"):
            bump = max(bump, 2)
        elif message.startswith("fix"):
            bump = max(bump, 1)
    if bump == 3:
        return f"{major + 1}.0.0"
    if bump == 2:
        return f"{major}.{minor + 1}.0"
    if bump == 1:
        return f"{major}.{minor}.{patch + 1}"
    return "no release"


def main():
    data = sys.stdin.read().split("\n")
    current = data[0].strip()
    n = int(data[1])
    print(next_version(current, data[2:2 + n]))


main()

import sys


def find_flaky(runs):
    """runs: list of (commit, test, PASS or FAIL). A test is flaky if it both passed and failed on the SAME commit. Return [(test, fail rate over all its runs as a whole percent rounded down)] sorted by test."""
    outcomes, runs_of, fails_of = {}, {}, {}
    for commit, test, result in runs:
        outcomes.setdefault((test, commit), set()).add(result)
        runs_of[test] = runs_of.get(test, 0) + 1
        fails_of[test] = fails_of.get(test, 0) + (result == "FAIL")
    flaky = {test for (test, _), seen in outcomes.items() if len(seen) == 2}
    return [(t, 100 * fails_of[t] // runs_of[t]) for t in sorted(flaky)]


def main():
    data = sys.stdin.read().split("\n")
    n = int(data[0])
    runs = [tuple(data[1 + i].split()) for i in range(n)]
    flaky = find_flaky(runs)
    if not flaky:
        print("NONE")
    for test, rate in flaky:
        print(test, f"{rate}%")


main()

import sys


def earliest_schedule(stages):
    """stages: {name: (minutes, [stages it needs first])}, a DAG; unlimited runners. A stage starts when all its prerequisites have finished (at 0 if it has none). Return ([(name, start, finish)] sorted by name, the time the whole pipeline finishes)."""
    finish = {}

    def done_at(name):                       # memoised depth-first search over prerequisites
        if name not in finish:
            minutes, deps = stages[name]
            finish[name] = max((done_at(d) for d in deps), default=0) + minutes
        return finish[name]

    for name in stages:
        done_at(name)
    schedule = [(n, finish[n] - stages[n][0], finish[n]) for n in sorted(stages)]
    return schedule, max(finish.values())


def main():
    data = sys.stdin.read().split("\n")
    n = int(data[0])
    stages = {}
    for i in range(n):
        name, minutes, deps = data[1 + i].split()
        stages[name] = (int(minutes), [] if deps == "-" else deps.split(","))
    schedule, total = earliest_schedule(stages)
    for name, start, finish in schedule:
        print(name, start, finish)
    print("total", total)


main()

import re
import sys


def scan(lines):
    """Return [(line number from 1, kind)] in line order; on one line check aws_key, then private_key, then password. aws_key: 'AKIA' followed by 16 characters that are capital letters or digits. private_key: the line contains '-----BEGIN' and 'PRIVATE KEY-----'. password: 'password' (any case) followed, after optional spaces, by '=' or ':' and a value that, with spaces and quote marks trimmed, is not empty and does not start with '${', 'os.environ', 'process.env' or 'getenv'."""
    aws = re.compile(r"AKIA[A-Z0-9]{16}")
    password = re.compile(r"password *[=:](.*)", re.IGNORECASE)
    safe = ("${", "os.environ", "process.env", "getenv")
    findings = []
    for number, line in enumerate(lines, 1):
        if aws.search(line):
            findings.append((number, "aws_key"))
        if "-----BEGIN" in line and "PRIVATE KEY-----" in line:
            findings.append((number, "private_key"))
        found = password.search(line)
        if found:
            value = found.group(1).strip(" '\"")
            if value and not value.startswith(safe):
                findings.append((number, "password"))
    return findings


def main():
    data = sys.stdin.read().split("\n")
    n = int(data[0])
    findings = scan(data[1:1 + n])
    if not findings:
        print("CLEAN")
    for line_no, kind in findings:
        print("line", line_no, kind)


main()
